"""Add cord module and real-image spinal-infection extension; keep original assets."""
from pathlib import Path
import json,re
A=Path('app/src/main/assets')
def js(name,obj): (A/name).write_text('export const data='+json.dumps(obj,ensure_ascii=False,indent=2)+';\n')
patterns=[
 ['compression','Компрессионная миелопатия','Сопоставьте очаг с максимальным стенозом и деформацией мозга. Протяжённый T2-сигнал может выходить за уровень компрессии.','T2-гиперинтенсивность сама по себе не доказывает миеломаляцию. Усиление возможно и при дегенеративной компрессии; миелопатия — клинический диагноз.'],
 ['ms','Рассеянный склероз','Чаще короткие периферические очаги, нередко дорсолатеральные, с неполным поперечным вовлечением. Проверьте множественность и мозг.','Центральный очаг тоже возможен. По одному спинальному очагу нельзя установить РС; диагностические критерии и клинический контекст оценивают отдельно.'],
 ['aqp4','AQP4-IgG / NMOSD','Подозрение усиливают центральный протяжённый очаг, отёк, значительное поперечное вовлечение и соответствующий клинический синдром.','LETM — непрерывное поражение ≥3 позвоночных сегментов, а не диагноз NMOSD. Короткие очаги не исключают заболевание; нужны клиника и серология.'],
 ['mog','MOGAD','Возможны поражение серого вещества с H-паттерном, протяжённый очаг и вовлечение конуса; усиление бывает слабым или отсутствует.','H-паттерн встречается и при других состояниях. Сигнал МРТ не определяет антительный статус; нормальная ранняя МРТ не закрывает клинический вопрос.'],
 ['ischemia','Ишемия спинного мозга','Учитывайте внезапное начало. Ищите ограничение диффузии с низким ADC и согласованный сосудистый паттерн; при возможности сопоставьте аорту.','Ранняя МРТ может быть отрицательной, DWI технически ограничена. «Глаза совы» неспецифичны; усиление на подострой стадии не исключает ишемию.'],
 ['davf','Дуральная АВ-фистула','При протяжённом отёке грудного мозга / конуса ищите расширенные перимедуллярные сосуды и венозный застой.','Flow voids могут быть незаметны. Отсутствие сосудов на рутинной МРТ не исключает фистулу; при подозрении нужна профильная сосудистая оценка.'],
 ['metabolic','Метаболическое поражение','Симметричный сигнал задних, иногда боковых канатиков требует сопоставления с B12, медью, лекарственным и токсическим анамнезом.','«Перевёрнутая V» поддерживает трактовое распределение, но не различает дефицит B12 и меди и не заменяет лабораторную диагностику.'],
 ['sarcoid','Саркоидоз и другие воспалительные процессы','Оцените дорсальное субпиальное, центральноканальное и лептоменингеальное усиление, другие отделы ЦНС и системные данные.','Trident-паттерн — ориентир, а не доказательство саркоидоза. Не списывайте длительное усиление автоматически на опухоль или РС.'],
 ['tumor','Интрамедуллярная опухоль','Отделите солидную массу от отёка и полости. Отметьте экспансию, положение в поперечнике, характер усиления, кровоизлияние и сосуды.','Эпендимома чаще центральная, астроцитома бывает эксцентричной; есть перекрытие. Гистологию и молекулярный тип нельзя установить по МРТ.'],
 ['hemangioblastoma','Гемангиобластома','Небольшой интенсивно усиливающийся узел, питающие сосуды и непропорционально большая сирингомиелическая полость — повод включить её в дифряд.','Сосудистый узел не равен автоматически гемангиобластоме. При множественности и подходящем анамнезе учитывают синдромальный контекст.'],
 ['cavernoma','Кавернома и кровь','Оцените смешанный сигнал, ободок гемосидерина, T2*/GRE или SWI и признаки свежего кровоизлияния.','Blooming увеличивает видимый размер. Кровь бывает и при опухоли / мальформации; выраженный отёк требует оценки в динамике и контексте.'],
 ['syrinx','Сирингомиелия и центральный канал','Проверьте ликвороподобный сигнал полости, её ширину и протяжённость, солидный узел, краниовертебральный переход и другие причины нарушения ликворотока.','Тонкий центральный канал не следует автоматически называть клинически значимой сирингомиелией. Если причина вне покрытия, обозначьте это.'],
 ['artifact','Артефакт или настоящий очаг','Подтвердите изменение сигнала на аксиальных изображениях и второй сагиттальной серии. Проверьте пульсацию ликвора, движение и усечение.','Отсутствие подтверждения на одной серии не всегда исключает маленький очаг. При недостаточном качестве пишите об ограничениях.']
]
algorithm=[
 ['1. Срочность и клиника','Темп начала, слабость, тазовые нарушения, боль, температура, онкоанамнез, операция / травма. Сначала исключите компрессию и другое неотложное осложнение.'],
 ['2. Компартмент','Интрамедуллярный процесс, интрадуральное экстрамедуллярное образование или эпидуральная компрессия? Смещение мозга и его расширение — разные признаки.'],
 ['3. Подтверждение очага','SAG T2 плюс вторая чувствительная серия и AX T2 через всю патологию. Один яркий участок на одной сагиттальной картинке недостаточен.'],
 ['4. Длина и поперечник','Уровни и длина в мм / позвоночных сегментах; один непрерывный очаг или несколько. Центр / периферия, серое / белое вещество, доля поперечника.'],
 ['5. Структура и активность','Размер мозга, T1/T2, полость, кровь, сосуды, характер усиления и DWI/ADC по задаче. Не называйте отёк солидной опухолью.'],
 ['6. Синтез','Сопоставьте МР-паттерн с клиникой, мозгом, лабораторными данными и предыдущими МРТ. Выдайте короткий ранжированный дифряд и ограничения.']
]
scan=[
 ['Базовый набор','SAG T2 и T1, дополнительная чувствительная серия STIR / PD по локальному протоколу; прицельные тонкие AX T2 через всю патологию.','Покрытие должно включать весь очаг и его границы; избегайте пропусков между аксиальными блоками.'],
 ['Воспалительный процесс','По задаче шейный и грудной мозг с конусом; головной мозг и зрительные нервы при соответствующей клинике.','Только поясничная МРТ не оценивает большую часть спинного мозга. Расширение покрытия не должно задерживать оценку опасной компрессии.'],
 ['Контраст','Сопоставимые T1 до / после Gd, SAG и AX через патологию; подавление жира при необходимости.','Отсутствие усиления не исключает воспаление, опухоль или ишемию. Без Gd характер усиления не оценён.'],
 ['Острая ишемия','При технической возможности DWI + ADC с прицельным покрытием; оценка сосудов / аорты по клиническому вопросу.','Нет универсального спинального ADC-порога. Артефактная DWI не считается отрицательной.'],
 ['Кровь и сосуды','T2*/GRE или доступная чувствительная к восприимчивости серия; МР-ангиография при сосудистом подозрении.','При подозрении на фистулу рутинная МРТ не заменяет специализированную оценку и при показаниях катетерную ангиографию.'],
 ['Контроль','Сопоставимые плоскости, покрытие, толщина и контрасты; отдельно измеряйте солидный компонент, отёк и полость.','Сравнивайте реальные изображения, а не только заключения. Срок определяют клинический вопрос и динамика.']
]
check=['Уровни и фактическое покрытие','Компартмент и связь с компрессией','Число, длина и поперечное распределение очагов','Расширение / атрофия мозга','Усиление и качество DWI/ADC','Полость, кровь и перимедуллярные сосуды','Сравнение и ограничения','Срочное осложнение и передача результата при необходимости']
js('spinal-cord-data.js',dict(patterns=patterns,algorithm=algorithm,scan=scan,checklist=check))
# New card follows the actual MRI anatomy card; preserve every previous item.
p=A/'anatomy-regions.js';s=p.read_text();regions=json.loads(s[s.index('['):].strip().removesuffix(';'));spine=next(r for r in regions if r['id']=='spine')
if not any(i['url']=='spinal-cord.html' for i in spine['items']):spine['items'].insert(1,dict(title='Спинной мозг · очаги и миелопатии',description='Реальные МРТ · компрессия · РС / NMOSD / MOGAD · ишемия · опухоли',url='spinal-cord.html',type='КЛИНИЧЕСКИЙ МОДУЛЬ',thumb='menu-thumbs/spinal-cord.svg',contentKind='clinical'))
next(i for i in spine['items'] if i['url']=='spinal-infection.html')['description']='Реальные снимки · Modic I · эпидуральное распространение · контроль'
p.write_text('export const regions='+json.dumps(regions,ensure_ascii=False,indent=2)+';\n')
(A/'menu-thumbs/spinal-cord.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 112 112"><rect width="112" height="112" rx="24" fill="#142a34"/><path d="M42 15Q34 40 43 62Q48 82 45 99M70 15Q78 40 69 62Q64 82 67 99" fill="none" stroke="#8bdacc" stroke-width="5"/><path d="M56 17V96" stroke="#527782" stroke-width="2"/><ellipse cx="58" cy="51" rx="7" ry="14" fill="#efa670"/></svg>''')
